public class Main {
    public static void main(String[] args) {
        int score = 85;

        // If-Else
        if (score >= 90) {
            System.out.println("A");
        } else if (score >= 80) {
            System.out.println("B");
        } else {
            System.out.println("C");
        }

        // Switch Expression (Java 14+ Style)
        String day = "SAT";
        String type = switch (day) {
            case "SAT", "SUN" -> "Weekend";
            case "MON" -> "Start";
            default -> "Weekday";
        };
        System.out.println(type);
    }
}
